tool_input.command:
$h=@{'User-Agent'='dsh-agent'}
foreach ($u in @('https://raw.githubusercontent.com/Fish-under-sea/dsh-our-free-model-fish/main/src/image-pricing.js','https://raw.githubusercontent.com/Fish-under-sea/dsh-our-free-model-fish/main/src/channel-visibility.js')) {
  Write-Output "=== $u ==="
  try { ((Invoke-WebRequest $u -Headers $h -TimeoutSec 25 -UseBasicParsing).Content -split "`n" | Select-Object -First 34) -join "`n" } catch { Write-Output "FAILED: $($_.Exception.Message)" }
  Write-Output ''
}
